import React, { useEffect, useRef, useState } from 'react';

/*
 * 화면 꾸미기: 테마(기본 / 글래스 / 커스텀 배경) + 입력칸 글자 크기.
 * 모두 이 기기(localStorage)에만 저장된다.
 */

export const THEMES = [
  { value: 'default', name: '기본',        desc: '깔끔한 흰 배경' },
  { value: 'glass',   name: '글래스',      desc: '반투명 유리 + 컬러 그라데이션' },
  { value: 'custom',  name: '커스텀 배경', desc: '내 사진을 배경으로' },
];
export const INPUT_SIZES = [
  { value: 12, name: '아주 작게' },
  { value: 13, name: '작게' },
  { value: 14, name: '보통' },
  { value: 16, name: '크게' },
];

function readLS(key, fallback) {
  try { const v = localStorage.getItem(key); return v === null ? fallback : v; } catch { return fallback; }
}
function writeLS(key, val) {
  try { localStorage.setItem(key, val); return true; } catch { return false; }
}

export function useAppearance() {
  const [theme, setTheme] = useState(() => readLS('theme', 'default'));
  const [bgImage, setBgImageState] = useState(() => readLS('bgImage', ''));
  const [bgVeil, setBgVeil] = useState(() => Number(readLS('bgVeil', '35')));
  const [inputSize, setInputSize] = useState(() => Number(readLS('inputSize', '14')));

  useEffect(() => {
    document.documentElement.dataset.theme = theme;
    writeLS('theme', theme);
  }, [theme]);
  useEffect(() => { writeLS('bgVeil', String(bgVeil)); }, [bgVeil]);
  useEffect(() => {
    document.documentElement.style.setProperty('--input-fs', `${inputSize}px`);
    writeLS('inputSize', String(inputSize));
  }, [inputSize]);

  const setBgImage = url => {
    if (url && !writeLS('bgImage', url)) {
      alert('사진이 너무 커서 저장하지 못했어요. 다른 사진으로 해보세요.');
      return false;
    }
    if (!url) { try { localStorage.removeItem('bgImage'); } catch { /* ignore */ } }
    setBgImageState(url);
    return true;
  };

  return { theme, setTheme, bgImage, setBgImage, bgVeil, setBgVeil, inputSize, setInputSize };
}

/* 테마 배경 레이어 (고정) */
export function AppBackground({ theme, bgImage, bgVeil }) {
  if (theme === 'glass') return <div className="app-bg app-bg-glass" aria-hidden="true" />;
  if (theme === 'custom') {
    return (
      <div className="app-bg app-bg-custom" aria-hidden="true"
        style={bgImage ? { backgroundImage: `url("${bgImage}")` } : undefined}>
        <div className="app-bg-veil" style={{ opacity: bgVeil / 100 }} />
      </div>
    );
  }
  return null;
}

async function compressBg(file) {
  const url = URL.createObjectURL(file);
  try {
    const img = await new Promise((res, rej) => {
      const i = new Image();
      i.onload = () => res(i);
      i.onerror = () => rej(new Error('사진을 읽지 못했어요'));
      i.src = url;
    });
    for (const [side, q] of [[1600, 0.8], [1280, 0.72], [1024, 0.65]]) {
      const s = Math.min(1, side / Math.max(img.naturalWidth, img.naturalHeight));
      const c = document.createElement('canvas');
      c.width = Math.round(img.naturalWidth * s);
      c.height = Math.round(img.naturalHeight * s);
      c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
      const out = c.toDataURL('image/jpeg', q);
      if (out.length < 1500000) return out;
    }
    throw new Error('사진이 너무 커요');
  } finally {
    URL.revokeObjectURL(url);
  }
}

/* 설정 화면 카드들 */
export function AppearanceSettings({ theme, setTheme, bgImage, setBgImage, bgVeil, setBgVeil, inputSize, setInputSize }) {
  const fileRef = useRef(null);
  const [busy, setBusy] = useState(false);

  const onFile = async e => {
    const f = e.target.files?.[0];
    e.target.value = '';
    if (!f) return;
    setBusy(true);
    try {
      if (setBgImage(await compressBg(f))) setTheme('custom');
    } catch (err) { alert(err.message); }
    setBusy(false);
  };

  return (
    <>
      <div className="setting-card">
        <h3>테마</h3>
        <div className="theme-grid">
          {THEMES.map(t => (
            <button key={t.value} className={`theme-opt${theme === t.value ? ' active' : ''}`}
              onClick={() => { setTheme(t.value); if (t.value === 'custom' && !bgImage) fileRef.current?.click(); }}>
              <span className={`theme-swatch theme-swatch-${t.value}`}
                style={t.value === 'custom' && bgImage ? { backgroundImage: `url("${bgImage}")` } : undefined} />
              <span className="theme-name">{t.name}</span>
              <span className="theme-desc">{t.desc}</span>
            </button>
          ))}
        </div>

        {theme === 'custom' && (
          <div className="theme-custom">
            <div className="theme-custom-row">
              <button className="theme-small-btn" onClick={() => fileRef.current?.click()} disabled={busy}>
                {busy ? '불러오는 중…' : bgImage ? '🖼 배경 사진 바꾸기' : '🖼 배경 사진 고르기'}
              </button>
              {bgImage && (
                <button className="theme-small-btn ghost" onClick={() => setBgImage('')}>지우기</button>
              )}
            </div>
            <label className="theme-slider">
              <span>배경 흐리게</span>
              <input type="range" min="0" max="80" step="5" value={bgVeil} onChange={e => setBgVeil(Number(e.target.value))} />
              <span className="theme-slider-val">{bgVeil}%</span>
            </label>
          </div>
        )}
        <input ref={fileRef} type="file" accept="image/*" style={{ display: 'none' }} onChange={onFile} />
      </div>

      <div className="setting-card">
        <h3>입력 글자 크기 <span className="setting-note">(입력칸만, 제목은 그대로)</span></h3>
        <div className="size-seg">
          {INPUT_SIZES.map(s => (
            <button key={s.value} className={inputSize === s.value ? 'active' : ''} onClick={() => setInputSize(s.value)}>
              {s.name}
            </button>
          ))}
        </div>
        <input type="text" className="size-preview" readOnly value="이렇게 보여요 · 가나다 ABC 123" />
      </div>
    </>
  );
}
